function table(client:Awaited<ReturnType<typeof createServiceClient>>,name:string){return client.from(`${SOLUTIONS_VIEW_PREFIX}${name}`)}
function arr(value:unknown):string[]{return Array.isArray(value)?value.map(String):[]}
function num(value:unknown,fallback=0){const parsed=Number(value);return Number.isFinite(parsed)?parsed:fallback}
function bool(value:unknown){return Boolean(value)}
function iso(value:unknown){return typeof value==='string'&&value?value:null}
function obj(value:unknown):Record<string,any>{return value&&typeof value==='object'&&!Array.isArray(value)?value as Record<string,any>:{}}
function code(prefix:string){return `${prefix}-${new Date().toISOString().replace(/\D/g,'').slice(0,14)}-${randomUUID().slice(0,6).toUpperCase()}`}

async function audit(client:any,actor:ActorContext,eventType:string,entityType:string,entityId:string,payload:Record<string,unknown>={}){
 await table(client,'audit_events').insert({tenant_key:SOLUTIONS_TENANT_KEY,event_type:eventType,entity_type:entityType,entity_id:entityId,actor_id:actor.id,actor_name:actor.name,actor_role:actor.role,payload})
 await table(client,'outbox_events').insert({tenant_key:SOLUTIONS_TENANT_KEY,event_type:eventType,aggregate_type:entityType,aggregate_id:entityId,payload:{...payload,actor:{id:actor.id,name:actor.name,role:actor.role}},status:'pending'})
}

