export async function selectJourneyScenario(scenarioId:string,actor:ActorContext){const client=await createServiceClient();const {data,error}=await table(client,'journey_scenarios').update({status:'pedagogical_validation',updated_at:new Date().toISOString()}).eq('id',scenarioId).select('*').single();if(error)throw error;await table(client,'journey_approvals').insert({tenant_key:SOLUTIONS_TENANT_KEY,scenario_id:scenarioId,stage:'selection',decision:'selected',approver_id:actor.id,approver_name:actor.name,approver_role:actor.role,note:'Selected for pedagogical validation.'});await audit(client,actor,'journey.plan_selected','journey_scenario',scenarioId,{});return data}
export async function createReadyPlanFromScenario(scenarioId:string,universe:'b2c'|'b2b',actor:ActorContext){const data=await loadSolutionsOverview();const scenario=data.journeyScenarios.find((item)=>item.id===scenarioId);if(!scenario)throw new Error('Journey scenario not found.');const request=data.journeyRequests.find((item)=>item.id===scenario.requestId);if(!request||request.universe!==universe)throw new Error('Journey commercial universe mismatch.');if(scenario.workloadFindings.length)throw new Error(`Journey workload findings must be resolved: ${scenario.workloadFindings.join(' ')}`);const id=randomUUID();const totalSessions=scenario.days.reduce((sum,day)=>sum+day.sessions.length,0);const totalMinutes=scenario.days.flatMap((day)=>day.sessions).reduce((sum,session)=>sum+session.durationMinutes,0);const {data:row,error}=await table(await createServiceClient(),'ready_learning_plans').insert({id,tenant_key:SOLUTIONS_TENANT_KEY,code:code(universe==='b2c'?'PLAN-B2C':'PLAN-B2B'),universe,version_no:1,status:'commercial_validation',name:scenario.name,scenario_id:scenario.id,learner_profile:scenario.targetLearner,objectives:[request.primaryObjectiveKey,...request.secondaryObjectiveKeys],release_ids:scenario.releaseIds,duration_days:request.durationDays,total_sessions:totalSessions,total_minutes:totalMinutes,price_dh:scenario.commercial.finalTotalDh,gross_margin_percent:scenario.commercial.grossMarginPercent,created_by:actor.id}).select('*').single();if(error)throw error;const client=await createServiceClient();await table(client,'ready_learning_plan_versions').insert({tenant_key:SOLUTIONS_TENANT_KEY,plan_id:id,version_no:1,snapshot:scenario,commercial_calculation:scenario.commercial,change_note:'Initial ready plan from selected journey scenario.',created_by:actor.id});await audit(client,actor,'journey.ready_plan_created','ready_learning_plan',id,{scenarioId});return mapReadyPlan(row)}
export async function approveReadyPlan(planId:string,note:string,actor:ActorContext){const client=await createServiceClient();const {data:plan,error:loadError}=await table(client,'ready_learning_plans').select('*').eq('id',planId).single();if(loadError)throw loadError;if(num(plan.gross_margin_percent)<0)throw new Error('Negative-margin plan cannot be approved.');const {data,error}=await table(client,'ready_learning_plans').update({status:'approved',approved_by:actor.name,approved_at:new Date().toISOString(),approval_note:note,updated_at:new Date().toISOString()}).eq('id',planId).select('*').single();if(error)throw error;await table(client,'journey_approvals').insert({tenant_key:SOLUTIONS_TENANT_KEY,scenario_id:plan.scenario_id,stage:'commercial',decision:'approved',approver_id:actor.id,approver_name:actor.name,approver_role:actor.role,note});await audit(client,actor,'journey.plan_approved','ready_learning_plan',planId,{note});return mapReadyPlan(data)}
export async function publishReadyPlan(planId:string,actor:ActorContext){const client=await createServiceClient();const {data:plan,error:loadError}=await table(client,'ready_learning_plans').select('*').eq('id',planId).single();if(loadError)throw loadError;if(plan.status!=='approved')throw new Error('Ready plan must be approved before publication.');const {data,error}=await table(client,'ready_learning_plans').update({status:'published',published_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq('id',planId).select('*').single();if(error)throw error;await audit(client,actor,'journey.plan_published','ready_learning_plan',planId,{});return mapReadyPlan(data)}

export async function createPriceBook(input:{code:string;label:string;universe:'b2c'|'b2b';effectiveFrom:string;effectiveUntil?:string|null},actor:ActorContext){const client=await createServiceClient();const {data,error}=await table(client,'price_books').insert({tenant_key:SOLUTIONS_TENANT_KEY,code:input.code,label:input.label,universe:input.universe,currency:'Dh',status:'draft',effective_from:input.effectiveFrom,effective_until:input.effectiveUntil||null,created_by:actor.id}).select('*').single();if(error)throw error;await audit(client,actor,'price_book.created','price_book',String(data.id),{universe:input.universe});return data}
export async function calculateAdHocPricing(input:{universe:'b2c'|'b2b';releaseIds:string[];quantities?:Record<string,number>;discountPercent?:number;taxPercent?:number;minimumMarginPercent?:number}){const data=await loadSolutionsOverview();const map=new Map(data.releases.map((release)=>[release.id,release]));const selected=input.releaseIds.map((id)=>map.get(id)).filter(Boolean) as EligibleRelease[];return calculateCommercial({universe:input.universe,items:selected.map((release)=>({release,quantity:input.quantities?.[release.id]||1})),discountPercent:input.discountPercent||0,taxPercent:input.taxPercent||0,minimumMarginPercent:input.minimumMarginPercent??(input.universe==='b2c'?40:30),deliveryDh:input.universe==='b2c'?20:0,supportDh:input.universe==='b2b'?60:0})}
export function actorFromUser(user:any):ActorContext{return{id:String(user?.id||user?.email||'unknown'),name:String(user?.full_name||user?.name||user?.email||'Utilisateur ANGELCARE'),role:String(user?.role||user?.role_key||'operator')}}
export function controlledOntology(){return ontologyOptions}
